# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
MT=[['希腊 meta','在……之后、之间；复合词中也表转变'],['现代构词 meta-','进一步发展出关于某事自身、在更高分析层次上的用法']]
PH=[['希腊 ta meta ta physika','排在《物理学》之后的那些著作'],['中世纪拉丁 metaphysica / 法语 metafisique → 英语 metaphysic(s)','著作标题 → 探究存在、因果等根本问题的哲学领域']]
def A(h,a,b):return h+[[a,b]]
WB=[
E('meta','/ˈmetə/','谈论自身的；关于某活动本身的〔口语〕；游戏中的主流策略〔名词〕','镜头往后退一步：电影开始讨论拍电影，笑话开始讨论怎样讲笑话。','由现代构词成分 meta- 独立成词；游戏名词义常缩自 metagame。',A(MT,'英语独立词 meta','关于自身、创作过程本身；游戏中超出单局操作的策略环境'),'a meta joke 可以是拿“讲笑话这件事”开玩笑。游戏里 the meta 常指当前流行或占优势的玩法组合，是 metagame 的缩略，不宜把 most effective tactics available 当成确定的历史词源。','a meta joke；a meta discussion；the current meta。','这里的 meta 不是所有以 met- 开头的词的统一解释；拉丁 mēta“界标”还有别的同形词来源。',('A film about making that very film can feel very meta.','一部讲述自身拍摄过程的电影，会让人觉得很有自我指涉意味。'),('The latest update changed the game’s meta.','最近的更新改变了游戏中占主流的打法。'),sources=['https://www.merriam-webster.com/dictionary/meta','https://en.wiktionary.org/wiki/meta#English']),
E('metaphysics','/ˌmetəˈfɪzɪks/','形而上学','先不只问这块石头多重，再追问：什么算存在？事物为什么还是同一个事物？因果是什么？','名称接希腊 ta meta ta physika“《物理学》之后的著作”，经中世纪拉丁语、法语等传入英语。',PH,'这门哲学讨论存在、同一性、因果、时间等根本问题，范围在不同时期有变化。名称通常与亚里士多德作品的编排相联系，不能简单解释成“神秘力量的科学”。词尾有 s，表示学科时通常搭配单数动词。','study metaphysics；questions of metaphysics；metaphysics is。','physics 研究自然现象的规律；metaphysics 追问一些更基础的概念与结构，不等于反对科学。',('Metaphysics asks what kinds of things exist.','形而上学追问有哪些类型的事物存在。'),('The course connects metaphysics with questions about time and identity.','这门课把形而上学与时间、同一性问题联系起来。'),sources=['https://www.etymonline.com/word/metaphysics','https://plato.stanford.edu/entries/metaphysics/']),
E('metaphysical','/ˌmetəˈfɪzɪkəl/','形而上学的；有关存在本质的；超感官的〔部分语境〕','问题从某件事怎样发生，转向“存在、心灵、现实究竟是什么”。','中古英语借自中世纪拉丁 metaphysicālis；现代可联系 metaphysics 与 -al。',PH[:1]+[['中世纪拉丁 metaphysica → metaphysicālis → 英语 metaphysical','形而上学 → 有关形而上学的']],'a metaphysical question 可以问时间是否独立存在。metaphysical 在灵性或文学语境还可能指超感官、抽象玄远的内容，但不能把这种用法强套给每篇哲学论文。','a metaphysical question；a metaphysical claim；metaphysical assumptions。','metaphorical 是比喻性的；metaphysical 讨论形而上学或超感官内容，后半部分不同，意思也不同。',('The novel raises metaphysical questions about personal identity.','小说提出了关于个人同一性的形而上学问题。'),('Their disagreement rests on different metaphysical assumptions.','他们的分歧源于不同的形而上学预设。'),sources=['https://www.etymonline.com/word/metaphysical','https://plato.stanford.edu/entries/metaphysics/']),
E('metaphysician','/ˌmetəfɪˈzɪʃən/','形而上学家','专门研究存在、因果、同一性等根本哲学问题的人。','可能经古法语 methafisicien 借入，也可能按 metaphysic 仿 physician 的形式构成；来源有不同分析。',PH[:1]+[['中世纪拉丁 metaphysica／法语 metafisique','哲学领域的名称'],['古法语 methafisicien 借入，或英语 metaphysic 仿 physician 构词 → metaphysician','两种来源分析都指向研究形而上学的人']],'不是把 meta 加到 physician 前面就成为“超能力医生”。常见哲学语境里，它说一个人的研究领域；有些历史性疗法语境另有引申用法，须结合上下文。','a contemporary metaphysician；a debate among metaphysicians。','physician 是医生；metaphysician 通常是哲学研究者，不能看到末尾相同就判职业相同。',('The metaphysician examined the problem of free will.','这位形而上学家研究了自由意志问题。'),('Two metaphysicians disagreed about the nature of time.','两位形而上学家对时间的本质意见不一。'),sources=['https://www.etymonline.com/word/metaphysician']),
E('metaphase','/ˈmetəfeɪz/','分裂中期〔细胞学〕','细胞快要分家了，染色体先在中部排好，准备分向两边。','meta- + phase“阶段”；在细胞分裂术语中命名一个阶段。',MT[:1]+[['现代细胞学 meta- + phase → metaphase','分裂过程中染色体排列在中部的阶段']],'以有丝分裂为例，中期染色体排列在赤道面附近，之后进入后期，姐妹染色单体分离。减数分裂也有中期，但第一次中期排列的是同源染色体对，不能把所有分裂过程画成完全相同。','during metaphase；metaphase chromosomes；the metaphase plate。','anaphase 是随后分离的后期；metaphase 重点在排列，不是已经完成两个新细胞。',('During metaphase, the chromosomes line up near the cell’s centre.','在分裂中期，染色体排列在细胞中部附近。'),('The student identified a cell in metaphase under the microscope.','学生在显微镜下认出一个处于分裂中期的细胞。'),sources=['https://www.genome.gov/genetics-glossary/Metaphase','https://openstax.org/books/biology-2e/pages/10-2-the-cell-cycle']),
E('metalogic','英 /ˌmetəˈlɒdʒɪk/；美 /ˌmetəˈlɑːdʒɪk/','元逻辑','先用一套规则推结论，再退一步检查：这套规则本身可靠、完整吗？','meta-“关于自身的分析” + logic。',A(MT,'现代术语 metalogic','把逻辑系统本身当成研究对象'),'用推理规则证明一个命题属于系统内的推理；研究该系统的可靠性、完备性、可判定性，则进入元逻辑。前缀在这里换的是研究层次，不是说推理更神奇。','study metalogic；a result in metalogic。','logic 可讨论具体推理；metalogic 关注逻辑系统的性质。并非任何很复杂的推理都叫 metalogic。',('The course introduces basic results in metalogic.','这门课介绍元逻辑的一些基本成果。'),('Metalogic studies properties of formal logical systems.','元逻辑研究形式逻辑系统的性质。'),sources=['https://plato.stanford.edu/entries/logic-classical/','https://en.wiktionary.org/wiki/metalogic#English']),
E('metadata','/ˈmetəˌdeɪtə/','元数据；描述数据的数据','照片是内容，拍摄时间、位置、尺寸这些标签是在描述这份内容。','meta-“关于……自身” + data“数据”。',A(MT,'现代术语 metadata','用数据说明另一份数据的属性、结构或背景'),'一张照片的拍摄时间、一篇文章的作者、文件的格式，都可以是 metadata。它不是“没用的附加信息”，也不一定总显示在文件正文里；用途是让资料更容易识别、管理和解释。','image metadata；metadata fields；remove metadata。','data 与 metadata 是相对角色：描述某份资料的标签，对另一个分析任务来说也可以成为研究数据。',('The image metadata includes the date the photo was taken.','图像元数据包含拍摄日期。'),('Accurate metadata makes the archive easier to search.','准确的元数据让档案更容易检索。'),sources=['https://csrc.nist.gov/glossary/term/metadata']),
E('metacognition','英 /ˌmetəkɒɡˈnɪʃən/；美 /ˌmetəkɑːɡˈnɪʃən/','元认知；对自己思考过程的觉察与调节','做题时再多问一句：我是真懂了，还是只是看答案觉得眼熟？','meta-“关于自身” + cognition“认知”，形成现代心理学术语。',A(MT,'现代心理学 metacognition','觉察、检查和调节自己的认知过程'),'你发现自己能认出单词却说不出意思，于是换成遮住中文自测，这就是在监控并调整学习。元认知不是单纯多想几遍，更不是让脑中评论自己的一切永远不停。','metacognition in learning；develop metacognition；research on metacognition。','cognition 是认知活动；metacognition 把自己的认知活动当成观察、管理对象。',('Checking whether I truly understand a paragraph involves metacognition.','检查自己是否真正读懂一段话，涉及元认知。'),('The lesson encourages metacognition by asking students to explain their strategies.','这节课让学生解释自己的解题策略，以促进元认知。'),sources=['https://dictionary.apa.org/metacognition','https://www.apa.org/ed/precollege/topss/teaching-resources','https://www.merriam-webster.com/dictionary/metacognition']),
E('metacognitive','英 /ˌmetəˈkɒɡnətɪv/；美 /ˌmetəˈkɑːɡnətɪv/','元认知的；与监控自身思考有关的','描述那种会检查自己是否学会、方法是否有效的能力或做法。','meta- + cognitive；与名词 metacognition 构成相关术语组。',A(MT,'现代术语 metacognitive','有关自我认知监控与调节的'),'metacognitive strategies 包括先定学习计划、过程中查漏、结束后复盘方法。它说的是策略所起的作用，不是一个学生被永久分成“有元认知”和“没元认知”两类。','metacognitive awareness；metacognitive strategies；metacognitive monitoring。','cognitive skills 可是记忆、注意和推理能力；metacognitive skills 关心怎样检查、管理这些活动。',('She used a metacognitive strategy to check her understanding.','她用了一种元认知策略来检查自己是否理解。'),('The journal helps students develop metacognitive awareness.','这本学习日志帮助学生觉察自己的学习过程。'),sources=['https://dictionary.apa.org/metacognition','https://www.apa.org/ed/precollege/topss/teaching-resources']),
E('metalanguage','/ˈmetəˌlæŋɡwɪdʒ/','元语言；用来描述语言的语言','用一句话说天气，是在使用语言；用一句话解释“名词是什么”，是在拿语言说明语言。','meta-“描述自身或另一层对象” + language。',A(MT,'英语 metalanguage','描述、分析语言所使用的语言系统'),'学习英语时，中文可以充当解释英语的元语言；英语也能解释英语。“noun”“past tense”是常见元语言词汇，但元语言不只是一张术语清单，也包括完整的描述。','grammatical metalanguage；use English as a metalanguage。','metalanguage 不是 metal“金属” + language，也不必是一种新创造的人工语言。',('The teacher used simple metalanguage to explain the sentence.','老师用简单的语法描述来解释这个句子。'),('In this lesson, Chinese serves as the metalanguage for discussing English.','在这节课里，中文充当讨论英语的元语言。'),sources=['https://www.merriam-webster.com/dictionary/metalanguage']),
E('metalinguistic','/ˈmetəlɪŋˌɡwɪstɪk/','元语言的；把语言本身当作对象的','听一句话时，不只关心它说什么，还能注意它用了什么词、句型或双关。','meta- + linguistic，仿照 metalanguage 的相关概念构成。',A(MT,'英语 metalanguage 概念 → metalinguistic','与谈论、分析语言本身有关的'),'metalinguistic awareness 是能退一步观察语言的意识。孩子发现“蝙蝠的 bat”和“球棒的 bat”同形不同义，就是注意到了词语本身的特点，而不仅仅在谈动物或运动。','metalinguistic awareness；metalinguistic knowledge；a metalinguistic comment。','linguistic 泛指语言相关；metalinguistic 更突出谈论、分析语言的这一层。',('The joke requires some metalinguistic awareness.','理解这个笑话需要对语言本身有一点觉察。'),('She made a metalinguistic comment about the word order.','她针对词序作了一条语言分析式的评论。'),sources=['https://www.merriam-webster.com/dictionary/metalinguistic']),
E('metatheory','英 /ˈmetəˌθɪəri/；美 /ˈmetəˌθiːəri/〔按构词的参考读法〕','元理论；关于理论的理论','先用理论解释世界，再回头比较这些理论建立在什么假设上、怎样算解释成功。','meta- + theory。',A(MT,'现代术语 metatheory','把理论自身的结构、假设、性质作为对象的理论'),'一套学习理论解释人怎样学习；研究不同学习理论采用哪些假设、解释标准是什么，就可能进入元理论层次。这个词不保证它比具体理论更正确，只说明研究对象换了。','a metatheory of；develop a metatheory；compare metatheories。','theory 的对象可能是外部现象；metatheory 的对象是理论。不要把 meta 误读成“必然更高级、更好”。',('The chapter outlines a metatheory for comparing different models.','这一章概述了用于比较不同模型的元理论。'),('Their debate moved from the theory itself to questions of metatheory.','他们的争论从具体理论转向了有关理论结构和基础的问题。'),sources=['https://www.merriam-webster.com/dictionary/metatheory']),
E('metaverse','英 /ˈmetəvɜːs/；美 /ˈmetəˌvɜːrs/','元宇宙；供人共同活动的持续性虚拟环境','把网络空间想成一个能进入、相遇、活动的世界，而不只是一页页网页。','meta- + universe 的后半部分 -verse；现代科幻造词，1992 年小说《雪崩》推广了这一名称。',MT[:1]+[['现代英语 meta- + universe → metaverse','借“超出、另一层世界”的构想命名虚拟环境']],'常指人们以数字身份共同活动的虚拟空间，具体技术与范围的说法并不完全统一。它不是某一个品牌名称本身，也不能仅凭词形推断所有虚拟世界已经彼此连通。','a virtual metaverse；meet in the metaverse；a metaverse platform。','universe 是宇宙、世界整体；这里 -verse 从 universe 截取，不是“诗句”的 verse。',('The novel imagines people meeting in a shared metaverse.','小说想象人们在一个共享的元宇宙中见面。'),('The exhibition explores how identity might work in the metaverse.','这次展览探讨数字身份在元宇宙中可能怎样呈现。'),sources=['https://www.merriam-webster.com/dictionary/metaverse','https://www.merriam-webster.com/words-at-play/meaning-of-metaverse']),
]
